/* Elements
0  N
1  H
2  O
3  C
*/

// Species
#define N2_ID 0
#define H_ID 1
#define H2_ID 2
#define O_ID 3
#define OH_ID 4
#define O2_ID 5
#define H2O2_ID 6
#define H2O_ID 7
#define HO2_ID 8
#define CO_ID 9
#define CH3_ID 10
#define CH2O_ID 11
#define CO2_ID 12
#define CH4_ID 13
#define C2H2_ID 14
#define C2H4_ID 15
#define CH2CO_ID 16
#define C2H6_ID 17
#define C_ID 18
#define CH_ID 19
#define HCO_ID 20
#define TXCH2_ID 21
