  // reaction 25:  CH + OH <=> H + HCO
  k_f = 30000000;
  qf[42] *= k_f;
  qr[42] *= k_f * (kc_fast ? (ge[4] * inv_ge[20] * inv_ge[1] * ge[19])
                           : exp(-(-g_RT[1] + g_RT[4] + g_RT[19] - g_RT[20])));
  // reaction 26:  CH + H2 <=> H + TXCH2
  k_f = 108000000 * exp(-(1564.73209365314) * invT);
  qf[43] *= k_f;
