    dqdci = (0 - 1) * q_nocor;
    J[661] -= dqdci; // dwdot[H]/d[SXCH2]
    J[663] -= dqdci; // dwdot[O]/d[SXCH2]
    J[664] += dqdci; // dwdot[OH]/d[SXCH2]
