    dqdci = (0 - 1) * q_nocor;
    J[721] -= dqdci; // dwdot[H]/d[C2H5]
    J[723] -= dqdci; // dwdot[O]/d[C2H5]
    J[724] += dqdci; // dwdot[OH]/d[C2H5]
