    dqdc[8] = q_nocor;
    dqdc[9] = 1.75 * q_nocor;
    dqdc[10] = q_nocor;
    dqdc[11] = q_nocor;
    dqdc[12] = 3.6 * q_nocor;
    dqdc[13] = 2 * q_nocor;
    dqdc[14] = q_nocor;
    dqdc[15] = q_nocor;
    dqdc[16] = q_nocor;
