  phi_r = sc[5];
  Kc = refCinv * (kc_fast ? (ge[5] * inv_ge[3] * inv_ge[3])
                          : exp(2.000000 * g_RT[3] - g_RT[5]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(2.000000 * h_RT[3]) + (h_RT[5]) + 1.000000);
