    dqdc[11] = q_nocor;
    dqdc[12] = 3.6 * q_nocor;
    dqdc[13] = 2 * q_nocor;
    dqdc[14] = q_nocor;
    dqdc[15] = q_nocor;
    dqdc[16] = q_nocor;
