    J[694] -= dqdci; // dwdot[OH]/d[C2H3]
    J[697] += dqdci; // dwdot[H2O]/d[C2H3]
    // d()/d[C2H5]
    dqdci = (0 - 1) * q_nocor;
    J[721] -= dqdci; // dwdot[H]/d[C2H5]
    J[724] -= dqdci; // dwdot[OH]/d[C2H5]
    J[727] += dqdci; // dwdot[H2O]/d[C2H5]
