  // reaction 83: HCO + H2O <=> CO + H + H2O
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[7] * sc[20];
  k_f = 2240000000000 * exp(-1 * logT - (8554.92486267982) * invT);
  dlnkfdT = -1 * invT + (8554.92486267982) * invT2;
