  // d()/d[H]
  dqdci = -k_r * sc[7] * sc[9];
  J[31] += dqdci; // dwdot[H]/d[H]
  J[39] += dqdci; // dwdot[CO]/d[H]
  J[50] -= dqdci; // dwdot[HCO]/d[H]
  // d()/d[H2O]
  dqdci = +k_f * sc[20] - k_r * sc[1] * sc[9];
  J[211] += dqdci; // dwdot[H]/d[H2O]
  J[219] += dqdci; // dwdot[CO]/d[H2O]
  J[230] -= dqdci; // dwdot[HCO]/d[H2O]
  // d()/d[CO]
  dqdci = -k_r * sc[1] * sc[7];
