  phi_r = sc[2] * sc[12];
  Kc = refCinv * (kc_fast ? (ge[2] * inv_ge[1] * inv_ge[1])
                          : exp(2.000000 * g_RT[1] - g_RT[2]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(2.000000 * h_RT[1] + h_RT[12]) + (h_RT[2] + h_RT[12]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
